import Foundation
import ImageIO

/// The first HEVC decode of a process waits for the hardware decoder: 62 ms wall (12 ms of it CPU) for a 16 px HEIC,
/// then ~2 ms (M4 Pro, macOS 26.6). `main` runs one on a 16 px HEIC at utility QoS while AppKit starts, so a HEIC
/// opened at launch decodes warm. It stays warm (measured after 45 s idle) and costs 3.4 MB.
public enum HEVCWarmUp {
    public static func run() {
        let start = Trace.now()
        guard let source = CGImageSourceCreateWithData(Data(tinyHEIC) as CFData, DecodeProbe.sourceOptions) else { return }
        if IOSurfaceSPI.surface(source, index: 0, subsample: 1) == nil {
            _ = CGImageSourceCreateImageAtIndex(source, 0, [kCGImageSourceShouldCacheImmediately: true] as CFDictionary)
        }
        Trace.log("HEVC warm-up \(String(format: "%.1f", Trace.ms(since: start))) ms")
    }

